func requestRestock(itemId: Int64, quantity: Int, storeID: UUID) async -> String? {
    do {
        var initialStatus: TransferStatus = .pending
        var sourceStoreId: UUID? = nil

        // Auto-route small requests to nearby stores bypassing the admin
        if quantity <= 3 {
            if let nearbyStoreId = try await SmartRoutingService.shared.calculateSourceStore(requestingStoreId: storeID, itemId: itemId, quantity: quantity) {
                initialStatus = .pendingStoreApproval
                sourceStoreId = nearbyStoreId
            }
        }

        let payload = TransferRequestInsert(
            itemId: itemId,
            requestingStoreId: storeID,
            quantity: quantity,
            status: initialStatus
        )

        // If we have a source_store_id to insert along with the payload
        struct RoutedTransferRequestInsert: Encodable {
            let item_id: Int64
            let requesting_store_id: UUID
            let quantity: Int
            let status: String
            let source_store_id: UUID?
        }

        let routedPayload = RoutedTransferRequestInsert(
            item_id: itemId,
            requesting_store_id: storeID,
            quantity: quantity,
            status: initialStatus.rawValue,
            source_store_id: sourceStoreId
        )

        try await SupabaseManager.shared.client
            .from("transfer_request")
            .insert(routedPayload)
            .execute()

        // Reload to get the fresh request in the list
        await load(storeID: storeID)
        return nil // success
    } catch {
        print("Restock request error: \(error)")
        return error.localizedDescription
    }
}

